#[derive(Debug, Clone, Default)]
struct Opts {
    depth: Option<usize>,
    aggr: Option<u64>,
    summary: bool,
    usage: bool,
    bytes: bool,
    files_only: bool,
    excludes: Vec<String>,
    no_hidden: bool,
    ascii: bool,
