            }
        } else {
            opts.paths.push(PathBuf::from(arg));
        }
        i += 1;
    }

    if summary_seen {
        opts.depth = Some(1);
        opts.aggr = Some(1048576);
    } else {
        if !depth_seen {
            opts.depth = Some(usize::MAX);
        } else if opts.depth.is_none() {
            opts.depth = Some(1);
        }
        if !aggr_seen {
            opts.aggr = Some(0);
        } else if opts.aggr.is_none() {
            opts.aggr = Some(1048576);
        }
    }

    Ok(opts)
}

