                            j = chars.len();
                        } else if i + 1 < raw_args.len() && !raw_args[i + 1].starts_with('-') {
                            i += 1;
                            let val = &raw_args[i];
                            opts.depth = val.parse::<usize>().ok().or(Some(1));
                        } else {
                            opts.depth = Some(1);
                        }
                    }
                    'a' => {
                        aggr_seen = true;
                        let rest: String = chars[j + 1..].iter().collect();
                        if !rest.is_empty() {
