#[derive(Debug, Clone)]
struct Node {
    name: String,
    total_size: u64,
    children: Vec<Node>,
    style: Option<String>,
}

fn get_node_size(meta: &fs::Metadata, usage: bool) -> u64 {
    if usage {
        meta.blocks() * 512
    } else {
        meta.len()
    }
}

fn build_tree(path: &Path, opts: &Opts, colors: Option<&LsColors>, is_top_level: bool) -> Option<Node> {
    let name = if path == Path::new("/") {
        "/".to_string()
    } else {
        path.file_name()
            .map(|s| s.to_string_lossy().to_string())
            .unwrap_or_else(|| path.to_string_lossy().to_string())
    };

    if !is_top_level {
        if opts.no_hidden && name.starts_with('.') {
            return None;
        }
        if opts.excludes.contains(&name) {
            return None;
        }
    }

    let meta = match fs::symlink_metadata(path) {
        Ok(m) => m,
        Err(e) => {
            eprintln!("Couldn't read {} ({:?})", name, e.kind());
            return None;
        }
    };

    let is_symlink = meta.file_type().is_symlink();
    let is_dir = meta.is_dir() && !is_symlink;
    let is_exec = (meta.mode() & 0o111) != 0;

    let style = if !opts.ascii {
        colors.and_then(|c| c.get_style(path, is_dir, is_symlink, is_exec))
    } else {
        None
    };

    let own_size = get_node_size(&meta, opts.usage);

    if !is_dir {
        return Some(Node {
            name,
            total_size: own_size,
            children: vec![],
            style,
        });
    }

    let mut children = Vec::new();
    let read_dir = match fs::read_dir(path) {
        Ok(rd) => rd,
        Err(e) => {
            eprintln!("Couldn't read {} ({:?})", name, e.kind());
            return Some(Node {
                name,
                total_size: own_size,
                children: vec![],
                style,
            });
        }
    };

    for entry in read_dir {
        let entry = match entry {
            Ok(e) => e,
            Err(e) => {
                eprintln!("Couldn't read {} ({:?})", name, e.kind());
                continue;
            }
        };
        let child_path = entry.path();
        if opts.files_only {
            let child_meta = match fs::symlink_metadata(&child_path) {
                Ok(m) => m,
                Err(_) => continue,
            };
            if child_meta.is_dir() && !child_meta.file_type().is_symlink() {
                continue;
            }
        }
        if let Some(child_node) = build_tree(&child_path, opts, colors, false) {
            children.push(child_node);
        }
    }

    let aggr_thresh = opts.aggr.unwrap_or(0);
    let mut final_children = Vec::new();
    let mut aggr_sum = 0u64;

    for child in children {
        if aggr_thresh > 0 && child.total_size < aggr_thresh {
            aggr_sum += child.total_size;
        } else {
            final_children.push(child);
        }
    }

    final_children.sort_by(|a, b| b.total_size.cmp(&a.total_size));

    if aggr_sum > 0 {
        final_children.push(Node {
            name: "<aggregated>".to_string(),
            total_size: aggr_sum,
            children: vec![],
            style: None,
        });
    }

    let children_total: u64 = final_children.iter().map(|c| c.total_size).sum();
    let total_size = own_size + children_total;

    Some(Node {
        name,
        total_size,
        children: final_children,
        style,
    })
}

fn format_size(size: u64, bytes_only: bool) -> String {
    if bytes_only {
        return format!("{} B", size);
    }
    if size < 1024 {
        format!("{} B", size)
    } else if size < 1024 * 1024 {
        format!("{:.2} KiB", size as f64 / 1024.0)
    } else if size < 1024 * 1024 * 1024 {
        format!("{:.2} MiB", size as f64 / (1024.0 * 1024.0))
    } else if size < 1024 * 1024 * 1024 * 1024 {
        format!("{:.2} GiB", size as f64 / (1024.0 * 1024.0 * 1024.0))
    } else {
        format!("{:.2} TiB", size as f64 / (1024.0 * 1024.0 * 1024.0 * 1024.0))
    }
}

fn calc_width(size: u64, denom: u64) -> usize {
    if denom == 0 {
        return 0;
    }
    let calc = (size as i128 * 33 - denom as i128) / denom as i128;
    calc.clamp(0, 32) as usize
}

fn render_tree(
    node: &Node,
    current_depth: usize,
    max_depth: usize,
    prefix_str: &str,
    ancestor_bar_starts: &[(usize, char)],
    inherited_ascii_width: Option<usize>,
    parent_bar_width: usize,
    parent_denom: u64,
    opts: &Opts,
) {
    if current_depth > max_depth {
        return;
    }

    let children = &node.children;
    if children.is_empty() {
        return;
    }

    for (i, child) in children.iter().enumerate() {
        let is_last = i == children.len() - 1;
        let connector = if is_last { "└─ " } else { "├─ " };
        let full_prefix = format!("{}{}", prefix_str, connector);

        let prefix_visible_len = full_prefix.chars().count();
        let name_visible_avail = if prefix_visible_len < 25 {
            25 - prefix_visible_len
        } else {
            0
        };

        let name_len = child.name.chars().count();
        let (truncated_name, padded_spaces) = if name_len > name_visible_avail {
            let trunc: String = child.name.chars().take(name_visible_avail).collect();
            (trunc, 0)
        } else {
            (child.name.clone(), 25 - (prefix_visible_len + name_len))
        };

        let colored_name = if let Some(ref style) = child.style {
            format!("\x1b[{}m{}\x1b[0m", style, truncated_name)
        } else {
            truncated_name
        };

        let part0 = format!("{}{}{}{}", full_prefix, colored_name, " ".repeat(padded_spaces), " ");

        // Calculate bar width and start position
        let bar_width = if opts.ascii {
            if let Some(w) = inherited_ascii_width {
                w
            } else {
                calc_width(child.total_size, parent_denom)
            }
        } else {
            if current_depth == 1 {
                calc_width(child.total_size, parent_denom)
            } else {
                let w_local = calc_width(child.total_size, parent_denom);
                (w_local * parent_bar_width) / 32
            }
        };

        let mut bar_start = 32 - bar_width;

        if !opts.ascii && current_depth > 1 {
            let parent_start = ancestor_bar_starts.last().map(|a| a.0).unwrap_or(0);
            if bar_start <= parent_start && parent_start < 32 {
                bar_start = parent_start + 1;
            }
        }

        let mut bar_chars = vec![' '; 32];

        if opts.ascii {
            for col in bar_start..32 {
                bar_chars[col] = '#';
            }
        } else {
            for &(anc_start, anc_shade) in ancestor_bar_starts {
                for col in anc_start..bar_start {
                    if col < 32 {
                        bar_chars[col] = anc_shade;
                    }
                }
            }
            for col in bar_start..32 {
                bar_chars[col] = '█';
            }
        }

        let bar_str: String = bar_chars.into_iter().collect();

        // Calculate percentage
        let pct = if node.total_size == 0 {
            0
        } else {
            (child.total_size * 100) / node.total_size
        };

        let pct_str = format!("{:>3}%", pct);
        let size_str = format!("{:>14}", format_size(child.total_size, opts.bytes));

        println!("{}│ {}│ {}{}", part0, bar_str, pct_str, size_str);

        // Recurse for child
        let next_prefix = format!("{}{}", prefix_str, if is_last { "   " } else { "│  " });
        let next_shade = match current_depth {
            1 => '░',
            2 => '▒',
            3 => '▓',
            _ => '█',
        };
        let mut next_ancestors = ancestor_bar_starts.to_vec();
        next_ancestors.push((bar_start, next_shade));

        let next_ascii_width = if opts.ascii {
            Some(bar_width)
        } else {
            None
        };

        let child_bar_width = 32 - bar_start;

        render_tree(
            child,
            current_depth + 1,
            max_depth,
            &next_prefix,
            &next_ancestors,
            next_ascii_width,
            child_bar_width,
            node.total_size,
            opts,
        );
    }
}

fn main() {
    let raw_args: Vec<String> = env::args().collect();
    let prog_name = raw_args[0].clone();

    let opts = match parse_args(raw_args) {
        Ok(o) => o,
        Err(err_msg) => {
            print_usage(&prog_name);
            eprintln!("{}", err_msg);
            process::exit(1);
        }
    };

    if opts.help {
        print_usage(&prog_name);
        process::exit(0);
    }

    if opts.version {
        println!("dutree version 0.2.18");
        process::exit(0);
    }

    let mut target_paths = opts.paths.clone();
    if target_paths.is_empty() {
        target_paths.push(PathBuf::from("."));
    }

    // Validate all paths exist
    for p in &target_paths {
        if fs::symlink_metadata(p).is_err() {
            eprintln!("path {} doesn't exist", p.display());
            process::exit(1);
        }
    }

    let colors = LsColors::from_env();
    let colors_ref = if !opts.ascii { colors.as_ref() } else { None };

    let root_node = if target_paths.len() == 1 {
        let p = &target_paths[0];
        let root = match build_tree(p, &opts, colors_ref, true) {
            Some(r) => r,
            None => process::exit(0),
        };
        root
    } else {
        let mut top_children = Vec::new();
        for p in &target_paths {
            if let Some(child) = build_tree(p, &opts, colors_ref, true) {
                top_children.push(child);
            }
        }
        top_children.sort_by(|a, b| b.total_size.cmp(&a.total_size));
        let total_size: u64 = top_children.iter().map(|c| c.total_size).sum();

        Node {
            name: "<collection>".to_string(),
            total_size,
            children: top_children,
            style: None,
        }
    };

    // Print Header
    let display_root_name = if target_paths.len() > 1 {
        "<collection>".to_string()
    } else {
        let p = &target_paths[0];
        if p == Path::new(".") || p == Path::new("./") {
            env::current_dir()
                .ok()
                .and_then(|cd| cd.file_name().map(|s| s.to_string_lossy().to_string()))
                .unwrap_or_else(|| ".".to_string())
        } else if p == Path::new("/") {
            "/".to_string()
        } else {
            p.file_name()
                .map(|s| s.to_string_lossy().to_string())
                .unwrap_or_else(|| p.to_string_lossy().to_string())
        }
    };

    println!(
        "[ {} {} ]",
        display_root_name,
        format_size(root_node.total_size, opts.bytes)
    );

    let top_level_denom = root_node
        .children
        .iter()
        .map(|c| c.total_size)
        .max()
        .unwrap_or(0);

    let max_depth = opts.depth.unwrap_or(usize::MAX);
    render_tree(&root_node, 1, max_depth, "", &[], None, 32, top_level_denom, &opts);
}
EOF
