#[derive(Debug, Clone, Default)]
struct Opts {
    depth: Option<usize>,
    aggr: Option<u64>,
    usage: bool,
    bytes: bool,
    files_only: bool,
    excludes: Vec<String>,
    no_hidden: bool,
    ascii: bool,
    help: bool,
    version: bool,
    paths: Vec<PathBuf>,
}

struct LsColors {
    dir: Option<String>,
    exec: Option<String>,
    symlink: Option<String>,
    file: Option<String>,
    exts: Vec<(String, String)>,
}

impl LsColors {
    fn from_env() -> Option<Self> {
        let val = env::var("LS_COLORS").ok()?;
        if val.is_empty() {
            return None;
        }
