use std::env;
use std::fs;
use std::os::unix::fs::MetadataExt;
use std::path::{Path, PathBuf};
use std::process;

#[derive(Debug, Clone, Default)]
struct Opts {
    depth: Option<usize>,
    aggr: Option<u64>,
    usage: bool,
    bytes: bool,
    files_only: bool,
    excludes: Vec<String>,
    no_hidden: bool,
    ascii: bool,
    help: bool,
    version: bool,
    paths: Vec<PathBuf>,
}

struct LsColors {
    dir: Option<String>,
    exec: Option<String>,
    symlink: Option<String>,
    file: Option<String>,
    exts: Vec<(String, String)>,
}

impl LsColors {
    fn from_env() -> Option<Self> {
        let val = env::var("LS_COLORS").ok()?;
        if val.is_empty() {
            return None;
        }
        let mut dir = None;
        let mut exec = None;
        let mut symlink = None;
        let mut file = None;
        let mut exts = Vec::new();

        for entry in val.split(':') {
            if entry.is_empty() {
                continue;
            }
            if let Some((k, v)) = entry.split_once('=') {
                match k {
                    "di" => dir = Some(v.to_string()),
                    "ex" => exec = Some(v.to_string()),
                    "ln" => symlink = Some(v.to_string()),
                    "fi" => file = Some(v.to_string()),
                    _ => {
                        if let Some(ext) = k.strip_prefix('*') {
                            exts.push((ext.to_string(), v.to_string()));
                        }
                    }
                }
            }
        }
        Some(LsColors {
            dir,
            exec,
            symlink,
            file,
            exts,
        })
    }

    fn get_style(&self, path: &Path, is_dir: bool, is_symlink: bool, is_exec: bool) -> Option<String> {
        if is_dir {
            return self.dir.clone();
        }
        if is_symlink {
            return self.symlink.clone();
        }
        if is_exec {
            return self.exec.clone();
        }
        if let Some(name) = path.file_name().and_then(|n| n.to_str()) {
            for (ext, style) in &self.exts {
                if name.ends_with(ext) {
                    return Some(style.clone());
                }
            }
        }
        self.file.clone()
    }
}

fn parse_aggr_str(s: &str) -> Result<u64, String> {
    if s.is_empty() {
        return Ok(1048576);
    }
    let digits_len = s.chars().take_while(|c| c.is_ascii_digit()).count();
    if digits_len == 0 {
        return Err(format!("invalid argument '{}'", s));
    }
    let num: u64 = s[..digits_len]
        .parse()
        .map_err(|_| format!("invalid argument '{}'", s))?;
    let rem = &s[digits_len..];
    if rem.len() > 1 {
        return Err(format!("invalid argument '{}'", s));
    }
    let mult = if rem.is_empty() {
        1
    } else {
        match rem.chars().next().unwrap() {
            'k' | 'K' => 1024,
            'm' | 'M' => 1024 * 1024,
            'g' | 'G' => 1024 * 1024 * 1024,
            'b' | 'B' => 1,
            _ => 1,
        }
    };
    Ok(num * mult)
}

fn print_usage(prog_name: &str) {
    println!("Usage: {} [options] <path> [<path>..]", prog_name);
    println!();
    println!("Options:");
    println!("    -d, --depth [DEPTH] show directories up to depth N (def 1)");
    println!("    -a, --aggr [N[KMG]] aggregate smaller than N B/KiB/MiB/GiB (def 1M)");
    println!("    -s, --summary       equivalent to -da, or -d1 -a1M");
    println!("    -u, --usage         report real disk usage instead of file size");
    println!("    -b, --bytes         print sizes in bytes");
    println!("    -f, --files-only    skip directories for a fast local overview");
    println!("    -x, --exclude NAME  exclude matching files or directories");
    println!("    -H, --no-hidden     exclude hidden files");
    println!("    -A, --ascii         ASCII characters only, no colors");
    println!("    -h, --help          show help");
    println!("    -v, --version       print version number");
}

fn parse_args(raw_args: Vec<String>) -> Result<Opts, String> {
    let mut opts = Opts::default();
    let mut i = 1;
    let mut depth_seen = false;
    let mut aggr_seen = false;
    let mut summary_seen = false;

    while i < raw_args.len() {
        let arg = &raw_args[i];
        if arg == "--" {
            i += 1;
            while i < raw_args.len() {
                opts.paths.push(PathBuf::from(&raw_args[i]));
                i += 1;
            }
            break;
        } else if arg.starts_with("--") {
            let opt_str = &arg[2..];
            if opt_str == "help" {
                opts.help = true;
            } else if opt_str == "version" {
                opts.version = true;
            } else if opt_str == "summary" {
                summary_seen = true;
            } else if opt_str == "usage" {
                opts.usage = true;
            } else if opt_str == "bytes" {
                opts.bytes = true;
            } else if opt_str == "files-only" {
                opts.files_only = true;
            } else if opt_str == "no-hidden" {
                opts.no_hidden = true;
            } else if opt_str == "ascii" {
                opts.ascii = true;
            } else if opt_str == "depth" || opt_str.starts_with("depth=") {
                depth_seen = true;
                if opt_str.starts_with("depth=") {
                    let val = &opt_str[6..];
                    opts.depth = val.parse::<usize>().ok().or(Some(1));
                } else {
                    opts.depth = Some(1);
                }
            } else if opt_str == "aggr" || opt_str.starts_with("aggr=") {
                aggr_seen = true;
                if opt_str.starts_with("aggr=") {
                    let val = &opt_str[5..];
                    let parsed = parse_aggr_str(val)?;
                    opts.aggr = Some(parsed);
                } else {
                    opts.aggr = Some(1048576);
                }
            } else if opt_str == "exclude" || opt_str.starts_with("exclude=") {
                if opt_str.starts_with("exclude=") {
                    opts.excludes.push(opt_str[8..].to_string());
                } else if i + 1 < raw_args.len() {
                    i += 1;
                    opts.excludes.push(raw_args[i].clone());
                } else {
                    return Err("Argument to option 'exclude' missing".to_string());
                }
            } else {
                return Err(format!("Unrecognized option: '{}'", opt_str));
            }
        } else if arg.starts_with('-') && arg.len() > 1 {
            let chars: Vec<char> = arg[1..].chars().collect();
            let mut j = 0;
            while j < chars.len() {
                let c = chars[j];
                match c {
                    'h' => opts.help = true,
                    'v' => opts.version = true,
                    's' => summary_seen = true,
                    'u' => opts.usage = true,
                    'b' => opts.bytes = true,
                    'f' => opts.files_only = true,
                    'H' => opts.no_hidden = true,
                    'A' => opts.ascii = true,
                    'd' => {
                        depth_seen = true;
                        let rest: String = chars[j + 1..].iter().collect();
                        if !rest.is_empty() {
                            opts.depth = rest.parse::<usize>().ok().or(Some(1));
                            j = chars.len();
                        } else if i + 1 < raw_args.len() && !raw_args[i + 1].starts_with('-') {
                            i += 1;
                            let val = &raw_args[i];
                            opts.depth = val.parse::<usize>().ok().or(Some(1));
                        } else {
                            opts.depth = Some(1);
                        }
                    }
                    'a' => {
                        aggr_seen = true;
                        let rest: String = chars[j + 1..].iter().collect();
                        if !rest.is_empty() {
                            let parsed = parse_aggr_str(&rest)?;
                            opts.aggr = Some(parsed);
                            j = chars.len();
                        } else if i + 1 < raw_args.len() && !raw_args[i + 1].starts_with('-') {
                            i += 1;
                            let val = &raw_args[i];
                            let parsed = parse_aggr_str(val)?;
                            opts.aggr = Some(parsed);
                        } else {
                            opts.aggr = Some(1048576);
                        }
                    }
                    'x' => {
                        let rest: String = chars[j + 1..].iter().collect();
                        if !rest.is_empty() {
                            opts.excludes.push(rest);
                            j = chars.len();
                        } else if i + 1 < raw_args.len() {
                            i += 1;
                            opts.excludes.push(raw_args[i].clone());
                        } else {
                            return Err("Argument to option 'x' missing".to_string());
                        }
                    }
                    _ => return Err(format!("Unrecognized option: '{}'", c)),
                }
                j += 1;
            }
        } else {
            opts.paths.push(PathBuf::from(arg));
        }
        i += 1;
    }

    if summary_seen {
        opts.depth = Some(1);
        opts.aggr = Some(1048576);
    } else {
        if !depth_seen {
            opts.depth = Some(usize::MAX);
        } else if opts.depth.is_none() {
            opts.depth = Some(1);
        }
        if !aggr_seen {
            opts.aggr = Some(0);
        } else if opts.aggr.is_none() {
            opts.aggr = Some(1048576);
        }
    }

    Ok(opts)
}

#[derive(Debug, Clone)]
struct Node {
    name: String,
    total_size: u64,
    children: Vec<Node>,
    style: Option<String>,
}

fn get_node_size(meta: &fs::Metadata, usage: bool) -> u64 {
    if usage {
        meta.blocks() * 512
    } else {
        meta.len()
    }
}

fn build_tree(path: &Path, opts: &Opts, colors: Option<&LsColors>, is_top_level: bool) -> Option<Node> {
    let name = if path == Path::new("/") {
        "/".to_string()
    } else {
        path.file_name()
            .map(|s| s.to_string_lossy().to_string())
            .unwrap_or_else(|| path.to_string_lossy().to_string())
    };

    if !is_top_level {
        if opts.no_hidden && name.starts_with('.') {
            return None;
        }
        if opts.excludes.contains(&name) {
            return None;
        }
    }

    let meta = match fs::symlink_metadata(path) {
        Ok(m) => m,
        Err(e) => {
            eprintln!("Couldn't read {} ({:?})", name, e.kind());
            return None;
        }
    };

    let is_symlink = meta.file_type().is_symlink();
    let is_dir = meta.is_dir() && !is_symlink;
    let is_exec = (meta.mode() & 0o111) != 0;

    let style = if !opts.ascii {
        colors.and_then(|c| c.get_style(path, is_dir, is_symlink, is_exec))
    } else {
        None
    };

    let own_size = get_node_size(&meta, opts.usage);

    if !is_dir {
        return Some(Node {
            name,
            total_size: own_size,
            children: vec![],
            style,
        });
    }

    let mut children = Vec::new();
    let read_dir = match fs::read_dir(path) {
        Ok(rd) => rd,
        Err(e) => {
            eprintln!("Couldn't read {} ({:?})", name, e.kind());
            return Some(Node {
                name,
                total_size: own_size,
                children: vec![],
                style,
            });
        }
    };

    for entry in read_dir {
        let entry = match entry {
            Ok(e) => e,
            Err(e) => {
                eprintln!("Couldn't read {} ({:?})", name, e.kind());
                continue;
            }
        };
        let child_path = entry.path();
        if opts.files_only {
            let child_meta = match fs::symlink_metadata(&child_path) {
                Ok(m) => m,
                Err(_) => continue,
            };
            if child_meta.is_dir() && !child_meta.file_type().is_symlink() {
                continue;
            }
        }
        if let Some(child_node) = build_tree(&child_path, opts, colors, false) {
            children.push(child_node);
        }
    }

    let aggr_thresh = opts.aggr.unwrap_or(0);
    let mut final_children = Vec::new();
    let mut aggr_sum = 0u64;

    for child in children {
        if aggr_thresh > 0 && child.total_size < aggr_thresh {
            aggr_sum += child.total_size;
        } else {
            final_children.push(child);
        }
    }

    final_children.sort_by(|a, b| b.total_size.cmp(&a.total_size));

    if aggr_sum > 0 {
        final_children.push(Node {
            name: "<aggregated>".to_string(),
            total_size: aggr_sum,
            children: vec![],
            style: None,
        });
    }

    let children_total: u64 = final_children.iter().map(|c| c.total_size).sum();
    let total_size = own_size + children_total;

    Some(Node {
        name,
        total_size,
        children: final_children,
        style,
    })
}

fn format_size(size: u64, bytes_only: bool) -> String {
    if bytes_only {
        return format!("{} B", size);
    }
    if size < 1024 {
        format!("{} B", size)
    } else if size < 1024 * 1024 {
        format!("{:.2} KiB", size as f64 / 1024.0)
    } else if size < 1024 * 1024 * 1024 {
        format!("{:.2} MiB", size as f64 / (1024.0 * 1024.0))
    } else if size < 1024 * 1024 * 1024 * 1024 {
        format!("{:.2} GiB", size as f64 / (1024.0 * 1024.0 * 1024.0))
    } else {
        format!("{:.2} TiB", size as f64 / (1024.0 * 1024.0 * 1024.0 * 1024.0))
    }
}

fn calc_width(size: u64, denom: u64) -> usize {
    if denom == 0 {
        return 0;
    }
    let calc = (size as i128 * 33 - denom as i128) / denom as i128;
    calc.clamp(0, 32) as usize
}

fn render_tree(
    node: &Node,
    current_depth: usize,
    max_depth: usize,
    prefix_str: &str,
    ancestor_bar_starts: &[(usize, char)],
    inherited_ascii_width: Option<usize>,
    top_level_denom: u64,
    opts: &Opts,
) {
    if current_depth > max_depth {
        return;
    }

    let children = &node.children;
    if children.is_empty() {
        return;
    }

    for (i, child) in children.iter().enumerate() {
        let is_last = i == children.len() - 1;
        let connector = if is_last { "└─ " } else { "├─ " };
        let full_prefix = format!("{}{}", prefix_str, connector);

        let prefix_visible_len = full_prefix.chars().count();
        let name_visible_avail = if prefix_visible_len < 25 {
            25 - prefix_visible_len
        } else {
            0
        };

        let name_len = child.name.chars().count();
        let (truncated_name, padded_spaces) = if name_len > name_visible_avail {
            let trunc: String = child.name.chars().take(name_visible_avail).collect();
            (trunc, 0)
        } else {
            (child.name.clone(), 25 - (prefix_visible_len + name_len))
        };

        let colored_name = if let Some(ref style) = child.style {
            format!("\x1b[{}m{}\x1b[0m", style, truncated_name)
        } else {
            truncated_name
        };

        let part0 = format!("{}{}{}{}", full_prefix, colored_name, " ".repeat(padded_spaces), " ");

        // Calculate bar width and start position
        let bar_width = if opts.ascii {
            if let Some(w) = inherited_ascii_width {
                w
            } else {
                calc_width(child.total_size, top_level_denom)
            }
        } else {
            calc_width(child.total_size, top_level_denom)
        };

        let mut bar_start = 32 - bar_width;

        if !opts.ascii && current_depth > 1 {
            let parent_start = ancestor_bar_starts.last().map(|a| a.0).unwrap_or(0);
            if bar_start <= parent_start && parent_start < 32 {
                bar_start = parent_start + 1;
            }
        }

        let mut bar_chars = vec![' '; 32];

        if opts.ascii {
            for col in bar_start..32 {
                bar_chars[col] = '#';
            }
        } else {
            for k in 0..ancestor_bar_starts.len() {
                let (anc_start, anc_shade) = ancestor_bar_starts[k];
                let next_start = if k + 1 < ancestor_bar_starts.len() {
                    ancestor_bar_starts[k + 1].0
                } else {
                    bar_start
                };
                for col in anc_start..next_start {
                    if col < 32 {
                        bar_chars[col] = anc_shade;
                    }
                }
            }
            for col in bar_start..32 {
                bar_chars[col] = '█';
            }
        }

        let bar_str: String = bar_chars.into_iter().collect();

        // Calculate percentage
        let pct = if node.total_size == 0 {
            0
        } else {
            (child.total_size * 100) / node.total_size
        };

        let pct_str = format!("{:>3}%", pct);
        let size_str = format!("{:>14}", format_size(child.total_size, opts.bytes));

        println!("{}│ {}│ {}{}", part0, bar_str, pct_str, size_str);

        // Recurse for child
        let next_prefix = format!("{}{}", prefix_str, if is_last { "   " } else { "│  " });
        let next_shade = match current_depth {
            1 => '░',
            2 => '▒',
            3 => '▓',
            _ => '█',
        };
        let mut next_ancestors = ancestor_bar_starts.to_vec();
        next_ancestors.push((bar_start, next_shade));

        let next_ascii_width = if opts.ascii {
            Some(bar_width)
        } else {
            None
        };

        render_tree(
            child,
            current_depth + 1,
            max_depth,
            &next_prefix,
            &next_ancestors,
            next_ascii_width,
            top_level_denom,
            opts,
        );
    }
}

fn main() {
    let raw_args: Vec<String> = env::args().collect();
    let prog_name = raw_args[0].clone();

    let opts = match parse_args(raw_args) {
        Ok(o) => o,
        Err(err_msg) => {
            print_usage(&prog_name);
            eprintln!("{}", err_msg);
            process::exit(1);
        }
    };

    if opts.help {
        print_usage(&prog_name);
        process::exit(0);
    }

    if opts.version {
        println!("dutree version 0.2.18");
        process::exit(0);
    }

    let mut target_paths = opts.paths.clone();
    if target_paths.is_empty() {
        target_paths.push(PathBuf::from("."));
    }

    // Validate all paths exist
    for p in &target_paths {
        if fs::symlink_metadata(p).is_err() {
            eprintln!("path {} doesn't exist", p.display());
            process::exit(1);
        }
    }

    let colors = LsColors::from_env();
    let colors_ref = if !opts.ascii { colors.as_ref() } else { None };

    let root_node = if target_paths.len() == 1 {
        let p = &target_paths[0];
        let root = match build_tree(p, &opts, colors_ref, true) {
            Some(r) => r,
            None => process::exit(0),
        };
        root
    } else {
        let mut top_children = Vec::new();
        for p in &target_paths {
            if let Some(child) = build_tree(p, &opts, colors_ref, true) {
                top_children.push(child);
            }
        }
        top_children.sort_by(|a, b| b.total_size.cmp(&a.total_size));
        let total_size: u64 = top_children.iter().map(|c| c.total_size).sum();

        Node {
            name: "<collection>".to_string(),
            total_size,
            children: top_children,
            style: None,
        }
    };

    // Print Header
    let display_root_name = if target_paths.len() > 1 {
        "<collection>".to_string()
    } else {
        let p = &target_paths[0];
        if p == Path::new(".") || p == Path::new("./") {
            env::current_dir()
                .ok()
                .and_then(|cd| cd.file_name().map(|s| s.to_string_lossy().to_string()))
                .unwrap_or_else(|| ".".to_string())
        } else if p == Path::new("/") {
            "/".to_string()
        } else {
            p.file_name()
                .map(|s| s.to_string_lossy().to_string())
                .unwrap_or_else(|| p.to_string_lossy().to_string())
        }
    };

    println!(
        "[ {} {} ]",
        display_root_name,
        format_size(root_node.total_size, opts.bytes)
    );

    let top_level_denom = root_node
        .children
        .iter()
        .map(|c| c.total_size)
        .max()
        .unwrap_or(0);

    let max_depth = opts.depth.unwrap_or(usize::MAX);
    render_tree(&root_node, 1, max_depth, "", &[], None, top_level_denom, &opts);
}
