fn parse_aggr_str(s: &str) -> Result<u64, String> {
    if s.is_empty() {
        return Ok(1048576);
    }
    let digits_len = s.chars().take_while(|c| c.is_ascii_digit()).count();
    if digits_len == 0 {
        return Err(format!("invalid argument '{}'", s));
    }
    let num: u64 = s[..digits_len]
        .parse()
        .map_err(|_| format!("invalid argument '{}'", s))?;
    let rem = &s[digits_len..];
    if rem.len() > 1 {
        return Err(format!("invalid argument '{}'", s));
    }
    let mult = if rem.is_empty() {
        1
    } else {
        match rem.chars().next().unwrap() {
            'k' | 'K' => 1024,
            'm' | 'M' => 1024 * 1024,
            'g' | 'G' => 1024 * 1024 * 1024,
            'b' | 'B' => 1,
            _ => 1,
        }
    };
    Ok(num * mult)
