use std::env;
use std::fs;
use std::os::unix::fs::MetadataExt;
use std::path::{Path, PathBuf};
use std::process;

#[derive(Debug, Clone, Default)]
struct Opts {
    depth: Option<usize>,
    aggr: Option<u64>,
    usage: bool,
    bytes: bool,
    files_only: bool,
    excludes: Vec<String>,
    no_hidden: bool,
    ascii: bool,
    help: bool,
    version: bool,
