struct LsColors {
    dir: Option<String>,
    exec: Option<String>,
    symlink: Option<String>,
    file: Option<String>,
    exts: Vec<(String, String)>,
}

impl LsColors {
    fn from_env() -> Option<Self> {
        let val = env::var("LS_COLORS").ok()?;
        if val.is_empty() {
            return None;
        }
        let mut dir = None;
        let mut exec = None;
        let mut symlink = None;
        let mut file = None;
        let mut exts = Vec::new();

