    }

    for (i, child) in children.iter().enumerate() {
        let is_last = i == children.len() - 1;
        let connector = if is_last { "└─ " } else { "├─ " };
        let full_prefix = format!("{}{}", prefix_str, connector);

        let prefix_visible_len = full_prefix.chars().count();
        let name_visible_avail = if prefix_visible_len < 25 {
            25 - prefix_visible_len
        } else {
            0
        };

        let name_len = child.name.chars().count();
        let (truncated_name, padded_spaces) = if name_len > name_visible_avail {
            let trunc: String = child.name.chars().take(name_visible_avail).collect();
            (trunc, 0)
        } else {
            (child.name.clone(), 25 - (prefix_visible_len + name_len))
        };

        let colored_name = if let Some(ref style) = child.style {
            format!("\x1b[{}m{}\x1b[0m", style, truncated_name)
        } else {
            truncated_name
        };

        let part0 = format!("{}{}{}{}", full_prefix, colored_name, " ".repeat(padded_spaces), " ");

        // Calculate bar width and start position
        let bar_width = if opts.ascii {
            if let Some(w) = inherited_ascii_width {
                w
            } else {
                calc_width(child.total_size, top_level_denom)
            }
        } else {
            if current_depth == 1 {
                calc_width(child.total_size, top_level_denom)
            } else {
                let w_local = calc_width(child.total_size, node.total_size);
                (w_local * parent_bar_width) / 32
            }
        };

        let mut bar_start = 32 - bar_width;

        if !opts.ascii && current_depth > 1 {
            let parent_start = ancestor_bar_starts.last().map(|a| a.0).unwrap_or(0);
            if bar_start <= parent_start && parent_start < 32 {
                bar_start = parent_start + 1;
            }
        }

        let mut bar_chars = vec![' '; 32];

        if opts.ascii {
            for col in bar_start..32 {
                bar_chars[col] = '#';
            }
        } else {
            for k in 0..ancestor_bar_starts.len() {
                let (anc_start, anc_shade) = ancestor_bar_starts[k];
                let next_start = if k + 1 < ancestor_bar_starts.len() {
                    ancestor_bar_starts[k + 1].0
                } else {
                    bar_start
                };
                for col in anc_start..next_start {
                    if col < 32 {
                        bar_chars[col] = anc_shade;
                    }
                }
            }
            for col in bar_start..32 {
                bar_chars[col] = '█';
            }
        }

        let bar_str: String = bar_chars.into_iter().collect();

        // Calculate percentage
        let pct = if node.total_size == 0 {
            0
        } else {
            (child.total_size * 100) / node.total_size
        };

        let pct_str = format!("{:>3}%", pct);
        let size_str = format!("{:>14}", format_size(child.total_size, opts.bytes));

        println!("{}│ {}│ {}{}", part0, bar_str, pct_str, size_str);

        // Recurse for child
        let next_prefix = format!("{}{}", prefix_str, if is_last { "   " } else { "│  " });
        let next_shade = match current_depth {
            1 => '░',
            2 => '▒',
            3 => '▓',
            _ => '█',
        };
        let mut next_ancestors = ancestor_bar_starts.to_vec();
        next_ancestors.push((bar_start, next_shade));

        let next_ascii_width = if opts.ascii {
            Some(bar_width)
        } else {
            None
        };

        let child_bar_width = 32 - bar_start;

        render_tree(
            child,
            current_depth + 1,
            max_depth,
            &next_prefix,
            &next_ancestors,
            next_ascii_width,
            child_bar_width,
            node.total_size,
            opts,
        );
    }
}

fn main() {
    let raw_args: Vec<String> = env::args().collect();
    let prog_name = raw_args[0].clone();

    let opts = match parse_args(raw_args) {
        Ok(o) => o,
        Err(err_msg) => {
            print_usage(&prog_name);
            eprintln!("{}", err_msg);
            process::exit(1);
        }
    };

    if opts.help {
        print_usage(&prog_name);
        process::exit(0);
    }

    if opts.version {
        println!("dutree version 0.2.18");
        process::exit(0);
    }

    let mut target_paths = opts.paths.clone();
    if target_paths.is_empty() {
        target_paths.push(PathBuf::from("."));
    }

    // Validate all paths exist
    for p in &target_paths {
        if fs::symlink_metadata(p).is_err() {
            eprintln!("path {} doesn't exist", p.display());
            process::exit(1);
        }
    }

    let colors = LsColors::from_env();
    let colors_ref = if !opts.ascii { colors.as_ref() } else { None };

    let root_node = if target_paths.len() == 1 {
        let p = &target_paths[0];
        let root = match build_tree(p, &opts, colors_ref, true) {
            Some(r) => r,
            None => process::exit(0),
        };
        root
    } else {
        let mut top_children = Vec::new();
        for p in &target_paths {
            if let Some(child) = build_tree(p, &opts, colors_ref, true) {
                top_children.push(child);
            }
        }
        top_children.sort_by(|a, b| b.total_size.cmp(&a.total_size));
        let total_size: u64 = top_children.iter().map(|c| c.total_size).sum();

        Node {
            name: "<collection>".to_string(),
            total_size,
            children: top_children,
            style: None,
        }
    };

    // Print Header
    let display_root_name = if target_paths.len() > 1 {
        "<collection>".to_string()
    } else {
        let p = &target_paths[0];
        if p == Path::new(".") || p == Path::new("./") {
            env::current_dir()
                .ok()
                .and_then(|cd| cd.file_name().map(|s| s.to_string_lossy().to_string()))
                .unwrap_or_else(|| ".".to_string())
        } else if p == Path::new("/") {
            "/".to_string()
        } else {
            p.file_name()
                .map(|s| s.to_string_lossy().to_string())
                .unwrap_or_else(|| p.to_string_lossy().to_string())
        }
    };

    println!(
        "[ {} {} ]",
        display_root_name,
        format_size(root_node.total_size, opts.bytes)
    );

    let top_level_denom = root_node
        .children
        .iter()
        .map(|c| c.total_size)
        .max()
        .unwrap_or(0);

    let max_depth = opts.depth.unwrap_or(usize::MAX);
    render_tree(&root_node, 1, max_depth, "", &[], None, 32, top_level_denom, &opts);
}
